spec.expr:
sum(
  count_over_time(
    {job="nginx_logs", filename="/var/log/nginx/access.log"}
    | pattern `<ip> - - [<timestamp>] "<method> <uri> <protocol>" <status> <size> "<referer>" "<agent>" "<extra>"<request_time>`
    | agent = "ELB-HealthChecker/2.0"
    | status >= 200
    | status < 300
    [2m]
  )
) > bool 0

